import{j as e}from"./blog-pages-Cba4hDr6.js";import{V as r}from"./_VerticalTemplate-Dp7us6hU.js";import"./accordion-DDCmwF38.js";import"./index-BYwBIDCw.js";import"./dt-3d-models-CYquM3AD.js";import"./index-Di8CS_45.js";const t={slug:"hydrogen-economy",industryDisplay:"Hydrogen Economy",industryShort:"green and blue hydrogen producers, electrolyzer OEMs, and fuel cell manufacturers",heroSubhead:"Specialist NDT cohorts for hydrogen production, transport, and storage — built around ASME B31.12 hydrogen piping, ASME VIII Div 2 for high-pressure hydrogen vessels, and the additional essential variables required for hydrogen-embrittlement-resistant inspection. Designed for NEOM-scale green hydrogen mega-projects and blue hydrogen with CCS retrofits.",primaryStandards:["ASME B31.12 (hydrogen piping)","ASME Section VIII Div 2","API 510","API 570","ASME Section V","EIGA Doc 100 (hydrogen)","ISO/TR 15916 (hydrogen safety)"],methods:[{method:"Ultrasonic Testing — PAUT for high-pressure hydrogen vessels + TOFD for thick-wall reformers",levels:"Level II → III",roleFit:"Hydrogen vessel inspectors, electrolyzer stack QC, ammonia carrier inspectors",codeRef:"ASME V Article 4, ASME VIII Div 2 Article 7, ASME B31.12 §GR-3"},{method:"Radiographic Testing — film + DR for hydrogen piping girth welds",levels:"Level I → III",roleFit:"Hydrogen pipeline weld QC, ammonia carrier RT crews",codeRef:"ASME V Article 2, API 1104, ASME B31.12 §IP-10"},{method:"Magnetic Particle Testing — WFMT for hydrogen-embrittlement surface screening",levels:"Level II",roleFit:"Hydrogen vessel fabrication QC, fuel cell bipolar plate inspectors",codeRef:"ASME V Article 7, ASTM E709, ASTM E1444"},{method:"Liquid Penetrant Testing — hydrogen-compatible PT chemistry",levels:"Level II",roleFit:"Stainless / Inconel hydrogen-service weld inspectors",codeRef:"ASME V Article 6, ASTM E165, ASTM E1417"},{method:"Hardness testing + replication for hydrogen-induced cracking surveillance",levels:"Level II specialist",roleFit:"Blue hydrogen reformer inspectors, ammonia loop integrity engineers",codeRef:"ASTM E384, ASTM E10, NACE MR0103 / ISO 17945"},{method:"Helium leak testing — hydrogen-system tightness verification",levels:"Level II",roleFit:"Electrolyzer stack commissioning, fuel cell QC",codeRef:"ASME V Article 10, ASTM E498, ASTM E499"},{method:"Visual Testing — hydrogen-embrittlement awareness",levels:"Level I → II",roleFit:"All hydrogen QC inspectors as a baseline",codeRef:"ASME V Article 9, ISO 17637"}],skillGaps:[{gap:"Process-piping QC crews transferred from oil &amp; gas with ASME B31.3 fluency but no B31.12 hydrogen essential-variable training",impact:"Hydrogen-induced cracking risk under-controlled; commissioning hydro-test failures and EPC schedule slippage measured in months."},{gap:"Pressure-vessel inspectors certified to ASME VIII Div 1 only, encountering hydrogen storage tanks fabricated to Div 2 acceptance criteria",impact:"Acceptance criteria misapplied; defects accepted that fail Div 2 fitness-for-service, or worse — defects rejected that were acceptable, driving costly rework."},{gap:"PAUT operators trained on hydrocarbon vessels who cannot defend scan plans on hydrogen embrittlement targets (sub-surface micro-cracks, HF-induced cracking)",impact:"Audit findings during commissioning by hydrogen offtakers (Yara, ADNOC, Aramco, Plug Power) and insurers — scan rejected, vessel re-inspected."},{gap:"Welding inspectors holding generic AWS CWI without hydrogen-specific filler-metal-traceability discipline",impact:"Heat-affected zone hardness exceedances on hydrogen-service welds; rework cost in the hundreds of thousands per spread on electrolyzer projects."},{gap:"Recurrent training cadence set at SNT-TC-1A's 5-year default rather than the annual recertification typical at hydrogen offtaker audits",impact:"Insurer surveys and offtaker pre-commissioning audits flag stale qualification records — commercial-operation-date slippage."}],tracks:[{role:"Hydrogen Plant Inspector (Production)",progression:"Level II UT + RT + MT + PT, then API 510 + ASME B31.12 bridging module",coreMethods:"UT, RT, MT, PT + API 510 inspector",hoursTotal:"240–280 instructor-led + 5-day API 510 + 3-day B31.12 module"},{role:"Electrolyzer / Fuel Cell QC Inspector",progression:"Level II UT + MT + PT + helium leak, plus stack-specific written practice",coreMethods:"UT, MT, PT, helium leak",hoursTotal:"200–240 instructor-led + OEM-stack OJT"},{role:"Hydrogen Pipeline Inspector",progression:"Level II UT + RT + MT, then API 1104 weld inspection + B31.12 transmission module",coreMethods:"UT, RT, MT + API 1104",hoursTotal:"200–240 instructor-led + 5-day API 1104 prep"},{role:"Ammonia / Hydrogen Carrier Vessel Inspector",progression:"Level II UT + RT + MT, then API 510 + NACE MR0103 (sour service)",coreMethods:"UT, RT, MT + API 510",hoursTotal:"240–280 instructor-led + 5-day API 510 prep"},{role:"Hydrogen Project HSE-NDT Lead",progression:"Level II VT + UT thickness + leak testing + ISO/TR 15916 module",coreMethods:"VT, UT thickness, helium leak",hoursTotal:"160–200 instructor-led + commissioning shadow"}],pricing:[{headcount:"10–24 engineers",perHead:"$1,400–$2,600 per head",notes:"Hydrogen-specific methods; B31.12 bridging module included."},{headcount:"25–49 engineers",perHead:"$1,200–$2,300 per head",notes:"Multi-method tracks across production + transport + storage."},{headcount:"50–99 engineers",perHead:"$1,050–$2,050 per head",notes:"Multi-site hydrogen EPC programme; dedicated lead instructor."},{headcount:"100+ engineers",perHead:"POA — typically $880–$1,750 per head",notes:"Multi-asset hydrogen mega-project annual contract; offtaker-specific written-practice bridging included."}],deliveryNote:"Hydrogen cohorts are dominated by hybrid delivery. Theory on the LMS during EPC mobilisation, on-site practicals at the electrolyzer OEM stack-test facility or the EPC's hydrogen-service spool fabrication shop two to four weeks before commissioning. PAUT calibration on hydrogen-specific reference blocks (representative of vessel base metal + cladding combinations) is delivered on the customer's own coupons so essential-variable transfer is genuine. Pure on-site delivery is reserved for radiography (regulatory licensing, source storage) and high-pressure helium leak testing.",complianceFootnote:"Hydrogen project compliance is governed by a fast-consolidating code stack — ASME B31.12 for piping, ASME VIII Div 2 for vessels, EIGA Doc 100 for industry safety, plus offtaker-specific written practices (NEOM, Yara, Plug Power, Air Liquide, Linde, Nel Hydrogen). We document training records SNT-TC-1A baseline + customer-written-practice overlay + B31.12/Div 2 essential-variable trace through each module. The evidence pack survives both insurer / lender surveys and offtaker commissioning audits without findings.",caseStudy:{headline:"Green hydrogen mega-project (Middle East) — 36-engineer multi-method cohort, 13-week programme",body:"A green hydrogen mega-project EPC needed to certify 36 in-house inspectors across UT Level II, RT Level II, MT/PT Level II, and seed 12 candidates for the API 510 inspector exam ahead of electrolyzer-train commissioning. Atlantis NDT delivered a hybrid cohort over 13 weeks: 7 weeks LMS theory in parallel with the spool-fabrication phase, 4 on-site practical weeks at the EPC's spool yard, then a 2-week API 510 + ASME B31.12 bridging block. First-attempt API 510 pass rate was 11 of 12; the one re-take passed inside the standard window. The hydrogen offtaker's lender's-engineer survey closed with no inspector-qualification findings, and total per-head cost landed 31% below the open-enrolment route the EPC had budgeted."},cityLinks:[{slug:"rotterdam",label:"Rotterdam"},{slug:"ruwais",label:"Ruwais"}],wordCountHint:"Hydrogen-economy NDT corporate training sits at the intersection of established pressure-vessel and piping inspection discipline (a 60-year code base in ASME VIII and ASME B31) and a fast-moving emerging code stack for hydrogen-specific service conditions (ASME B31.12, EIGA Doc 100, ISO/TR 15916, plus offtaker-specific written practices). Our hydrogen cohorts are designed for the buyers actually deploying capital — green hydrogen mega-project EPCs at NEOM scale, blue hydrogen retrofits on existing reformers (Yara, CF Industries, Linde, Air Liquide), electrolyzer OEMs scaling stack-fabrication (Nel Hydrogen, Plug Power, ITM Power), and ammonia / liquid-organic hydrogen carrier midstream operators. The skill gap that dominates hydrogen training procurement is the gap between ASME B31.3 process-piping QC fluency (which most candidates already have) and the additional essential-variable discipline that B31.12 requires for hydrogen service — filler metal chemistry traceability, heat-affected zone hardness control, post-weld heat treatment trace, and hydrogen-induced cracking surveillance via hardness testing + replication. We do not waste cohort time re-teaching B31.3 to engineers who already passed it; instead, we run a 3-day B31.12 bridging module that explicitly maps the additional essential variables onto the engineer's existing B31.3 muscle memory. The second skill gap, especially common at green hydrogen mega-projects, is the move from ASME VIII Div 1 vessel inspection acceptance criteria to Div 2 acceptance criteria for high-pressure hydrogen storage. Engineers who have spent careers on Div 1 hydrocarbon vessels frequently misapply Div 1 thresholds on Div 2 vessels, with accept / reject decisions falling out by tens of percent. Our Div 2 module is taught alongside PAUT scan-plan defence, so the engineer not only knows the new acceptance threshold but can write a scan plan that the lender's-engineer surveyor will accept on the first pass. Recurrent training cadence is the third area where hydrogen projects diverge from oil &amp; gas — most hydrogen offtakers require annual recertification rather than the SNT-TC-1A 5-year default, and our recurrent calendar is built to fit that cadence. Send the asset mix (electrolyzer / reformer / pipeline / storage), the offtaker, the EPC scope, and headcount — we respond inside two business days with a written training plan, indicative quote, and an SNT-TC-1A + B31.12 mapped written practice ready to layer on top of your own corporate written practice."};function d(){return e.jsx(r,{config:t})}export{d as default};
